        x = own.get("x", 0)
        y = own.get("y", 0)
        # Prefer staying or moving to a free adjacent cell
        def is_free(px, py):
            if grid is None:
                return True
            if py < 0 or px < 0:
                return False
            if py >= len(grid):
                return False
            row = grid[py] if isinstance(grid, (list, tuple)) and py < len(grid) else None
            if row is None or not isinstance(row, (list, tuple)):
                return True
            if px >= len(row):
                return True
            cell = row[px]
            return cell in (0, None, "empty")
        # check 4-neighborhood
        moves = [ (0,0), (1,0), (-1,0), (0,1), (0,-1) ]
        for dx, dy in moves:
            nxp, nyp = x + dx, y + dy
            if is_free(nxp, nyp):
                return [dx, dy]
        # fallback
        return [0,0]
    else:
        # Guess a small safe move
        return [0, 0]

